        static <T> BubbleSort<T> createDefault() {
            return new Builder<T>().build();
        }

        static <T> BubbleSort<T> createWithoutMetrics(Comparator<T> comparator) {
            return new Builder<T>().withComparator(comparator).trackMetrics(false).build();
        }
    }

    public static void main(String[] args) {
        BubbleSort<Integer> sorter = Factory.createDefault();

        Integer[] data = {64, 34, 25, 12, 22, 11, 90};
        sorter.sort(data);
        System.out.println("Sorted array: " + Arrays.toString(data));
        System.out.println("Statistics: " + sorter.getStatistics());

        List<String> strings = new ArrayList<>(Arrays.asList("zebra", "apple", "mango", "banana"));
        sorter.resetStatistics();
        sorter.sort(strings);
        System.out.println("Sorted strings: " + strings);
        System.out.println("Statistics: " + sorter.getStatistics());
    }
}
